function ChaoticRecallMgr:GetTeamInfoByQuestId(questId,index)
    local questVo = ChaoticRecallUtils.GetChaoticRecallLevelVo(questId)
    local teamInfo = nil
    if not isNull(questVo) then
        local nodeId = questVo.nodeId
        local nodeVo = ChaoticRecallUtils.GetChaoticRecallNodeVo(nodeId)
        if checkNumber(nodeVo.groupId) > 0 then
            local homeDojo = self:GetHomeDojo()
            local groups = homeDojo:GetGroups()
            for i, v in pairs(groups) do
                if checkNumber(v.groupId) == checkNumber(nodeVo.groupId) then
                    teamInfo = checkTable(v.nodes[nodeVo.place].teamInfo)
                    break
                end
            end
        end
    end

    if not isNull(index) then
        if not isNull(teamInfo) and teamInfo[index] then
            return teamInfo[index]
        else
            return nil
        end
    else
        return teamInfo
    end

    return nil
end

